def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1 << 20), b''):
            digest.update(block)
    return digest.hexdigest()


def write_json(path, value):
    with Path(path).open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')


def tree_files(path):
    path = Path(path)
    require(path.is_dir(), 'Missing source-built directory: ' + str(path))
    files = {}
    for child in sorted(path.rglob('*')):
        require(not child.is_symlink(), 'Snapshot input contains a symlink: ' + str(child))
        if child.is_file():
            files[child.relative_to(path).as_posix()] = {'bytes': child.stat().st_size, 'sha256': sha(child)}
    require(files, 'Empty snapshot input: ' + str(path))
    return files


def tree_sha(files):
    digest = hashlib.sha256()
    for name in sorted(files, key=Path):
        digest.update(name.encode() + b'\0')
        digest.update(bytes.fromhex(files[name]['sha256']))
    return digest.hexdigest()


def file_record(path):
    path = Path(path).resolve(strict=True)
    return {'path': str(path), 'bytes': path.stat().st_size, 'sha256': sha(path)}


def classpath_manifest(paths):
    result = []
    for path in paths:
        if path.is_dir():
            files = tree_files(path)
            result.append({'path': str(path), 'kind': 'tree', 'files': len(files), 'sha256': tree_sha(files)})
        else:
            result.append({'path': str(path), 'kind': 'file', 'sha256': sha(path)})
    return result


def copy_tree(source, destination):
    before = tree_files(source)
    shutil.copytree(source, destination)
    require(tree_files(destination) == before == tree_files(source), 'Class tree changed during copy: ' + str(source))
    return before


def copy_sources(origin, names, destination):
    records, paths = {}, []
    for name in names:
        source, target = origin / name, destination / name
        before = file_record(source)
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source, target)
        require(sha(target) == before['sha256'] == sha(source), 'Source changed during copy: ' + str(source))
        records[name] = {'origin': before, 'copy': file_record(target)}
        paths.append(target)
    return records, paths


def run(out, label, argv, environment):
    argv = [str(item) for item in argv]
    record = {'argv': argv, 'cwd': str(ROOT), 'startedEpochNs': time.time_ns()}
    write_json(out / (label + '-command.json'), record)
    print(label + ' started', flush=True)
    status = {'exitCode': None, 'exception': None}
    try:
        with (out / (label + '.log')).open('xb') as log:
            process = subprocess.run(argv, cwd=ROOT, env=environment, stdout=log, stderr=subprocess.STDOUT)
        status['exitCode'] = process.returncode
    except Exception as error:
        status['exception'] = type(error).__name__ + ': ' + str(error)
        raise
    finally:
        status['finishedEpochNs'] = time.time_ns()
        write_json(out / (label + '-result.json'), status)
    require(status['exitCode'] == 0, label + ' failed; preserve ' + str(out / (label + '.log')))
    print(label + ' exited 0', flush=True)


def verify_retained_sources(baseline, direct):
    def region(text, begin, end):
        require(text.count(begin) == text.count(end) == 1, 'Ambiguous retained source region')
        start = text.index(begin)
        return text[start:text.index(end, start)]
    old_materializer = (baseline / EVALUATION / 'NativeResultMaterializer.java').read_text()
    new_materializer = (direct / EVALUATION / 'NativeResultMaterializer.java').read_text()
    boundary = '/**\n * Evaluation-local last-value memo.'
    require(old_materializer.count(boundary) == new_materializer.count(boundary) == 1,
            'Materializer plan boundary changed')
    require(old_materializer.split(boundary)[0] == new_materializer.split(boundary)[0],
            'Retained Plan source, imports or line positions differ')
    begin = '\t/** Last validated coordinates for each target, invalidated by accumulated source-slot changes. */'
    end = '\tprivate boolean allocate(NativeLmdbQuerySource currentSource) {'
    require(region(old_materializer, begin, end) == region(new_materializer, begin, end),
            'Retained FactorMemo/FactorPage source differs')
    old_bindings = (baseline / EVALUATION / 'NativeProjectedBindingSet.java').read_text()
    new_bindings = (direct / EVALUATION / 'NativeProjectedBindingSet.java').read_text()
    for begin, end in [
        ('\t/** Immutable row-independent projection metadata compiled once with its owning native row step. */',
         '\tstatic boolean enabled() {'),
        ('\t@Override\n\tpublic Iterator<Binding> iterator() {', '\t@Override\n\tpublic Set<String> getBindingNames() {')]:
        require(region(old_bindings, begin, end) == region(new_bindings, begin, end),
                'Retained ProjectionLayout/anonymous iterator source differs')
    return {'planPrefixIdentical': True, 'factorNestedSourceIdentical': True,
            'projectionLayoutSourceIdentical': True, 'bindingIteratorSourceIdentical': True}


