        write_json(out / 'source-copies.json', all_sources)
        shutil.copyfile(common_provenance, out / 'common-source-provenance.json')
        shutil.copyfile(direct_source_receipt, out / 'direct-source-receipt.json')
        source_identity = 'retention-source-built-sha256-' + tree_sha(source_before)
